import{_ as a,o as n,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/plugins.md","filePath":"es-ES/user-guide/settings/plugins.md","lastUpdated":1785214938000}'),t={name:"es-ES/user-guide/settings/plugins.md"};function s(i,e,l,u,p,d){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>Lista cada plugin instalado, con la versión del SDK de Plugins cargada actualmente mostrada como una insignia en la cabecera de la página (relevante si estás comparando un plugin con el <a href="./../../dev-guide/">Manual de Desarrollador</a>).</p><h2 id="tarjeta-por-plugin" tabindex="-1">Tarjeta por plugin <a class="header-anchor" href="#tarjeta-por-plugin" aria-label="Permalink to &quot;Tarjeta por plugin&quot;">​</a></h2><p>Cada plugin instalado obtiene una tarjeta que muestra su icono, nombre, versión, nombre de archivo de la DLL, y una <strong>descripción general de la función</strong>.</p><p>Haz clic en la tarjeta para expandirla y ver sus componentes registrados, agrupados por tipo (proveedores de búsqueda, proveedores de menú dinámico, etc.) — cada componente activable tiene su propia <strong>casilla de habilitar/deshabilitar</strong>; un componente marcado como obligatorio muestra en su lugar un icono de candado y no se puede desactivar. Pasar el cursor sobre un componente revela su <strong>tooltip detallado de función</strong>.</p><p>Cuando un grupo (o el plugin en su conjunto) tiene más de un componente activable, aparece un enlace <strong>Seleccionar todo / Deseleccionar todo</strong> junto a su encabezado, que permite marcar/desmarcar todas las casillas de ese ámbito a la vez en lugar de una por una.</p><p>Si un plugin expone su propia configuración (ajustes personalizados más allá de un simple habilitar/deshabilitar), aparece un botón <strong>Configurar</strong> en la cabecera de la tarjeta, que abre el propio diálogo de configuración de ese plugin.</p><p>Un banner en la parte inferior de la página recuerda que algunos interruptores de componente solo surten efecto tras reiniciar SwiftList.</p><p>Si no hay ningún plugin instalado, la página muestra en su lugar un mensaje de estado vacío.</p><p>Para ver un ejemplo concreto de cómo es en la práctica el propio diálogo <strong>Configurar</strong> de un plugin (por ejemplo, cambiar una palabra clave de activación), ver <a href="./../instant-answers.html">Respuestas instantáneas y atajos de palabra clave</a>.</p>',10)])])}const m=a(t,[["render",s]]);export{g as __pageData,m as default};
